void source_run_physics_pool_startup_runtime(M &m,std::uint32_t entry,
    SourcePhysicsContactRuntimeAbi &abi,SourcePhysicsContactImage image,FP fp,
    const SourcePhysicsContactRuntimeServices &services,const O &observe) {
    if(image!=SourcePhysicsContactImage::MapPack11&&image!=SourcePhysicsContactImage::TitleUpdate15)
        throw std::runtime_error("Unverified physics contact executable image");
    FpScope scope(fp);WorldState s{m,observe,services,image};s.load(abi);
    try {
        switch(entry) {
case 0x11e150u:run_11e150(s);break;
case 0x11e180u:run_11e180(s);break;
case 0x16d070u:run_16d070(s);break;
case 0x16d0d0u:run_16d0d0(s);break;
case 0x16d210u:run_16d210(s);break;
case 0x16d220u:run_16d220(s);break;
case 0x16d2c0u:run_16d2c0(s);break;
case 0x16d4c0u:run_16d4c0(s);break;
case 0x16d560u:run_16d560(s);break;
case 0x1d2620u:run_1d2620(s);break;
case 0x2284c0u:run_2284c0(s);break;
case 0x228540u:run_228540(s);break;
case 0x326970u:run_326970(s);break;
case 0x33785cu:run_33785c(s);break;
case 0x33788au:run_33788a(s);break;

        default:throw std::runtime_error("Required original contact entry unavailable");
        }
    } catch(...) {abi=s.save();throw;}
    abi=s.save();
}
